// Canonical topic and text normalizer for MPSC Manager
// Handles:
// 1. Unicode NFC normalization (composes Devanagari characters and diacritics)
// 2. Strips all zero-width and invisible control characters commonly generated by mobile keyboards (Gboard/IME):
//    - \u200B (Zero Width Space)
//    - \u200C (Zero Width Non-Joiner - ZWNJ)
//    - \u200D (Zero Width Joiner - ZWJ)
//    - \uFEFF (Byte Order Mark / Zero Width No-Break Space)
//    - \u00AD (Soft Hyphen)
//    - \u200E, \u200F, \u202A-\u202E (Directional marks)
//    - \u2060 (Word Joiner)
// 3. Normalizes all unicode spaces (\u00A0 non-breaking space, \u2000-\u200A, etc.) to standard ASCII space
// 4. Collapses multiple consecutive spaces into a single space and trims edges
// 5. Cleans trailing/leading punctuation
export const normalizeTopicName = (rawTopic, fallback = 'General Practice') => {
  if (!rawTopic || typeof rawTopic !== 'string') return fallback;
  
  // 1. Unicode NFC normalization
  let cleaned = rawTopic.normalize('NFC');
  
  // 2. Strip zero-width & invisible characters
  cleaned = cleaned.replace(/[\u200B-\u200D\uFEFF\u00AD\u200E\u200F\u202A-\u202E\u2060]/g, '');
  
  // 3. Normalize all unicode spaces to standard space
  cleaned = cleaned.replace(/[\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]/g, ' ');
  
  // 4. Collapse multiple spaces into one and trim
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  
  // 5. Remove trailing colons, semicolons, dashes, or dots
  cleaned = cleaned.replace(/[:\-–—\.]+$|^[:\-–—\.]+/, '').trim();
  
  return cleaned || fallback;
};
